// src/components/common/TransactionForm.jsx
import React, { useState, useEffect } from 'react';
import { extractDateFromTransactionId } from '../../utils/helpers.js';
import './TransactionForm.css';

const TransactionForm = ({ 
  title, 
  isReplacement, 
  isExcess,
  txData, 
  onChange, 
  onSubmit, 
  onCancel,
  isPending = false,
  representative
}) => {
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    onChange({ target: { name, value } });
  };

  // Auto-extract date when transaction ID changes
  const handleTxIdChange = (e, field) => {
    const value = e.target.value;
    onChange({ target: { name: field, value } });
    
    // Extract date from primary transaction ID
    if (field === 'primaryTxId' && value && value.length >= 8) {
      const extractedDate = extractDateFromTransactionId(value);
      if (extractedDate) {
        onChange({ target: { name: 'date', value: extractedDate } });
      }
    }
  };

  // Determine if we need to show excess fields
  const showExcessFields = isExcess && isReplacement;

  return (
    <div className="claim-card transaction-container">
      <div className="transaction-title">{title}</div>
      <div className="tx-form">
        {isPending ? (
          <div className="field">
            <label>Transaction Amount</label>
            <div className="status-pending">⏳ Pending (Customer Care)</div>
            <div className="helper-text">Customer care will fill the amount</div>
          </div>
        ) : (
          <>
            {/* Primary Transaction (Previous/Base) */}
            <div className="field">
              <label>
                {showExcessFields ? 'Previous Transaction Amount *' : 'Transaction Amount *'}
              </label>
              <input
                type="text"
                name="primaryAmount"
                value={txData.primaryAmount || ''}
                onChange={handleInputChange}
                placeholder={showExcessFields ? "e.g., 250000 (base amount)" : "e.g., 250000"}
                required
                className={showExcessFields ? 'primary-amount' : ''}
              />
              {showExcessFields && (
                <div className="helper-text">
                  <i className="fas fa-info-circle"></i> 
                  This is the base amount from the original claim
                </div>
              )}
            </div>

            <div className="field">
              <label>
                {showExcessFields ? 'Previous Transaction ID *' : 'Transaction ID *'}
              </label>
              <input
                type="text"
                name="primaryTxId"
                value={txData.primaryTxId || ''}
                onChange={(e) => handleTxIdChange(e, 'primaryTxId')}
                placeholder={showExcessFields ? "e.g., MP260610.2000.X08195 (base ID)" : "e.g., MP260610.2000.X08195"}
                required
                className={showExcessFields ? 'primary-txid' : ''}
              />
              {showExcessFields && (
                <div className="helper-text">
                  <i className="fas fa-info-circle"></i> 
                  This is the ID from the original transaction
                </div>
              )}
            </div>

            {/* Excess/Extra Transaction (Only for Excess Replacement) */}
            {showExcessFields && (
              <div className="excess-section">
                <div className="excess-divider">
                  <span>➕ Excess Top-up</span>
                </div>
                <div className="field">
                  <label>Top-up Amount *</label>
                  <input
                    type="text"
                    name="excessAmount"
                    value={txData.excessAmount || ''}
                    onChange={handleInputChange}
                    placeholder="e.g., 50000 (extra amount)"
                  />
                  <div className="helper-text">
                    <i className="fas fa-info-circle"></i> 
                    Additional amount for upgrading to a better device
                  </div>
                </div>

                <div className="field">
                  <label>Top-up Transaction ID *</label>
                  <input
                    type="text"
                    name="excessTxId"
                    value={txData.excessTxId || ''}
                    onChange={(e) => handleTxIdChange(e, 'excessTxId')}
                    placeholder="e.g., MP260611.3000.X08196"
                  />
                  <div className="helper-text">
                    <i className="fas fa-info-circle"></i> 
                    Transaction ID for the top-up amount
                  </div>
                </div>
              </div>
            )}
          </>
        )}
        
        <div className="field">
          <label>Transaction Date</label>
          <input
            type="text"
            name="date"
            value={txData.date}
            readOnly
            className="readonly"
          />
          {txData.date && txData.date !== 'Invalid Date' && (
            <div className="helper-text success">
              <i className="fas fa-check-circle"></i> 
              Date auto-extracted from Previous Transaction ID
            </div>
          )}
          {showExcessFields && (
            <div className="helper-text">
              <i className="fas fa-info-circle"></i> 
              Date is from the previous transaction, not the top-up
            </div>
          )}
        </div>
        
        <div className="field">
          <label>Representative</label>
          <input
            type="text"
            value={representative || 'Shabani'}
            disabled
            className="readonly"
          />
        </div>
        
        <div className="form-actions">
          <button type="button" className="btn-outline" onClick={onCancel}>Cancel</button>
          <button 
            type="button" 
            className="submit-btn" 
            onClick={onSubmit}
            disabled={!txData.primaryTxId || !txData.primaryAmount || (showExcessFields && (!txData.excessAmount || !txData.excessTxId))}
          >
            <i className="fas fa-check"></i> 
            {isPending ? 'Send to Customer Care' : 'Submit'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default TransactionForm;
